#!/usr/bin/env python3
# Coloca o MODELO 3D LEVE dentro do Dashboard (sem tela separada).
# Uso:  python3 /root/instalar_3d_dashboard.py     (o arquivo maquina.glb pode estar em /root)
import os, sys, re, io, base64, shutil, zipfile, datetime, subprocess
BASE = sys.argv[1] if len(sys.argv) > 1 else "/root/site_esteira"
VIEWS = os.path.join(BASE, "views"); PUB = os.path.join(BASE, "public")
CARD = base64.b64decode("").decode("utf-8"); VENDOR = base64.b64decode("")
res = []; carimbo = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
dash = os.path.join(VIEWS, "dashboard.html"); basehtml = os.path.join(VIEWS, "base.html")
if not os.path.exists(dash): print("❌ Nao achei " + dash); sys.exit(1)
for f in (dash, basehtml):
    if os.path.exists(f): shutil.copy2(f, f + ".bak_" + carimbo)
d = open(dash, encoding="utf-8").read()
if "dash3d-card" in d: res.append("⏭️  Dashboard: modelo 3D ja estava na tela.")
else:
    m = re.search(r"\{%\s*block content\s*%\}", d)
    if not m: res.append("❌ Dashboard: nao achei {% block content %}. Me mande o dashboard.html.")
    else: open(dash, "w", encoding="utf-8").write(d[:m.end()] + "\n" + CARD + "\n" + d[m.end():]); res.append("✅ Dashboard: card do modelo 3D adicionado no topo.")
if os.path.exists(basehtml):
    b = open(basehtml, encoding="utf-8").read()
    n = re.sub(r'\s*<a href="/modelo3d"[\s\S]*?</a>', "", b)
    if n != b: open(basehtml, "w", encoding="utf-8").write(n); res.append("✅ Menu: item separado 'Modelo 3D' removido (agora fica no Dashboard).")
    else: res.append("⏭️  Menu: nao havia item separado de Modelo 3D.")
os.makedirs(os.path.join(PUB, "modelo"), exist_ok=True)
if os.path.exists(os.path.join(PUB, "vendor3d", "three.module.min.js")): res.append("⏭️  three.js local: ja instalado.")
else:
    with zipfile.ZipFile(io.BytesIO(VENDOR)) as z: z.extractall(PUB)
    res.append("✅ three.js local instalado em public/vendor3d.")
for origem in ("/root/maquina.glb", os.path.join(os.path.dirname(os.path.abspath(__file__)), "maquina.glb")):
    if os.path.exists(origem):
        shutil.copy2(origem, os.path.join(PUB, "modelo", "maquina.glb")); res.append("✅ Modelo copiado: " + origem + " -> public/modelo/maquina.glb"); break
else:
    if not os.path.exists(os.path.join(PUB, "modelo", "maquina.glb")): res.append("⚠️  Falta o arquivo: copie maquina.glb para " + os.path.join(PUB, "modelo") + " (ou para /root e rode de novo).")
print("\n".join(res))
if not any(l.startswith("❌") for l in res): print("\nPronto. Reinicie:  sudo systemctl restart site_esteira   e aperte Ctrl+Shift+R.")
